create temp table reserved(label text primary key,id uuid,storage_path text,actor uuid);
grant all on reserved to authenticated,service_role;
create function pg_temp.reserve_fixture(p_ticket uuid,p_name text default 'note.txt',p_mime text default 'text/plain',p_size integer default 4,p_org uuid default 'f8200000-0000-4000-8000-000000000001')
returns table(id uuid,storage_path text) language sql as $$
 select * from public.reserve_ticket_attachment(p_org,p_ticket,(select revision from public.tickets where tickets.id=p_ticket),
 (select access_revision::bigint from public.ticket_context(p_org)),(select scope_revision from public.ticket_context(p_org)),p_name,p_mime,p_size);
$$;
reset role;set local role authenticated;set local request.jwt.claims='{"sub":"f8100000-0000-4000-8000-000000000007","role":"authenticated","app_role":"super_admin"}';
