select extensions.is((select count(*) from public.attachments where id=(select id from reserved where label='a-own'))::integer,0,'Uploading metadata is hidden a-own');
select extensions.throws_ok('select public.ticket_attachment(''f8200000-0000-4000-8000-000000000001'',''f8400000-0000-4000-8000-000000000001'',(select id from reserved where label=''a-own''))','42501',null,'Uploading download metadata denied a-own');
